PRAGMA foreign_keys = ON;

CREATE TABLE businesses (id TEXT PRIMARY KEY NOT NULL, name TEXT NOT NULL, legal_name TEXT, website TEXT, phone TEXT, email TEXT, created_at INTEGER NOT NULL DEFAULT (unixepoch()*1000), updated_at INTEGER NOT NULL DEFAULT (unixepoch()*1000));
CREATE TABLE locations (id TEXT PRIMARY KEY NOT NULL, business_id TEXT NOT NULL REFERENCES businesses(id) ON DELETE CASCADE, name TEXT NOT NULL, address_line_1 TEXT NOT NULL, address_line_2 TEXT, city TEXT NOT NULL, region TEXT NOT NULL, postal_code TEXT NOT NULL, country_code TEXT NOT NULL DEFAULT 'US', phone TEXT, timezone TEXT NOT NULL, hours_json TEXT NOT NULL DEFAULT '{}', created_at INTEGER NOT NULL DEFAULT (unixepoch()*1000), updated_at INTEGER NOT NULL DEFAULT (unixepoch()*1000));
CREATE INDEX locations_business_idx ON locations(business_id);
CREATE TABLE brand_profiles (id TEXT PRIMARY KEY NOT NULL, business_id TEXT NOT NULL REFERENCES businesses(id) ON DELETE CASCADE, voice TEXT NOT NULL DEFAULT '', audience TEXT NOT NULL DEFAULT '', visual_style TEXT NOT NULL DEFAULT '', created_at INTEGER NOT NULL DEFAULT (unixepoch()*1000), updated_at INTEGER NOT NULL DEFAULT (unixepoch()*1000));
CREATE UNIQUE INDEX brand_profiles_business_uidx ON brand_profiles(business_id);
CREATE TABLE brand_rules (id TEXT PRIMARY KEY NOT NULL, brand_profile_id TEXT NOT NULL REFERENCES brand_profiles(id) ON DELETE CASCADE, rule_type TEXT NOT NULL, value TEXT NOT NULL, enabled INTEGER NOT NULL DEFAULT 1, created_at INTEGER NOT NULL DEFAULT (unixepoch()*1000), updated_at INTEGER NOT NULL DEFAULT (unixepoch()*1000));
CREATE INDEX brand_rules_profile_idx ON brand_rules(brand_profile_id);
CREATE TABLE menu_categories (id TEXT PRIMARY KEY NOT NULL, business_id TEXT NOT NULL REFERENCES businesses(id) ON DELETE CASCADE, name TEXT NOT NULL, description TEXT, sort_order INTEGER NOT NULL DEFAULT 0, active INTEGER NOT NULL DEFAULT 1, created_at INTEGER NOT NULL DEFAULT (unixepoch()*1000), updated_at INTEGER NOT NULL DEFAULT (unixepoch()*1000));
CREATE INDEX menu_categories_business_idx ON menu_categories(business_id);
CREATE TABLE menu_items (id TEXT PRIMARY KEY NOT NULL, category_id TEXT NOT NULL REFERENCES menu_categories(id) ON DELETE CASCADE, name TEXT NOT NULL, description TEXT, price_cents INTEGER NOT NULL CHECK(price_cents >= 0), currency TEXT NOT NULL DEFAULT 'USD', ingredients_json TEXT NOT NULL DEFAULT '[]', allergen_json TEXT NOT NULL DEFAULT '[]', active INTEGER NOT NULL DEFAULT 1, created_at INTEGER NOT NULL DEFAULT (unixepoch()*1000), updated_at INTEGER NOT NULL DEFAULT (unixepoch()*1000));
CREATE INDEX menu_items_category_idx ON menu_items(category_id);
CREATE TABLE media_assets (id TEXT PRIMARY KEY NOT NULL, business_id TEXT NOT NULL REFERENCES businesses(id) ON DELETE CASCADE, kind TEXT NOT NULL CHECK(kind IN ('image','video','audio')), local_path TEXT NOT NULL, original_filename TEXT NOT NULL, mime_type TEXT NOT NULL, byte_size INTEGER NOT NULL CHECK(byte_size >= 0), width INTEGER, height INTEGER, duration_ms INTEGER, checksum_sha256 TEXT, source TEXT NOT NULL DEFAULT 'import', metadata_json TEXT NOT NULL DEFAULT '{}', created_at INTEGER NOT NULL DEFAULT (unixepoch()*1000), updated_at INTEGER NOT NULL DEFAULT (unixepoch()*1000));
CREATE INDEX media_assets_business_idx ON media_assets(business_id); CREATE UNIQUE INDEX media_assets_path_uidx ON media_assets(local_path);
CREATE TABLE menu_item_media (id TEXT PRIMARY KEY NOT NULL, menu_item_id TEXT NOT NULL REFERENCES menu_items(id) ON DELETE CASCADE, media_asset_id TEXT NOT NULL REFERENCES media_assets(id) ON DELETE CASCADE, sort_order INTEGER NOT NULL DEFAULT 0, created_at INTEGER NOT NULL DEFAULT (unixepoch()*1000), updated_at INTEGER NOT NULL DEFAULT (unixepoch()*1000));
CREATE UNIQUE INDEX menu_item_media_pair_uidx ON menu_item_media(menu_item_id, media_asset_id);
CREATE TABLE promotions (id TEXT PRIMARY KEY NOT NULL, business_id TEXT NOT NULL REFERENCES businesses(id) ON DELETE CASCADE, name TEXT NOT NULL, description TEXT NOT NULL, coupon_code TEXT, starts_at INTEGER NOT NULL, ends_at INTEGER NOT NULL, terms TEXT, active INTEGER NOT NULL DEFAULT 1, created_at INTEGER NOT NULL DEFAULT (unixepoch()*1000), updated_at INTEGER NOT NULL DEFAULT (unixepoch()*1000), CHECK(ends_at > starts_at));
CREATE INDEX promotions_business_dates_idx ON promotions(business_id, starts_at, ends_at);
CREATE TABLE campaigns (id TEXT PRIMARY KEY NOT NULL, business_id TEXT NOT NULL REFERENCES businesses(id) ON DELETE CASCADE, name TEXT NOT NULL, objective TEXT, starts_at INTEGER, ends_at INTEGER, status TEXT NOT NULL DEFAULT 'draft', created_at INTEGER NOT NULL DEFAULT (unixepoch()*1000), updated_at INTEGER NOT NULL DEFAULT (unixepoch()*1000), CHECK(ends_at IS NULL OR starts_at IS NULL OR ends_at > starts_at));
CREATE INDEX campaigns_business_idx ON campaigns(business_id);
CREATE TABLE content_items (id TEXT PRIMARY KEY NOT NULL, business_id TEXT NOT NULL REFERENCES businesses(id) ON DELETE CASCADE, campaign_id TEXT REFERENCES campaigns(id) ON DELETE SET NULL, promotion_id TEXT REFERENCES promotions(id) ON DELETE SET NULL, title TEXT NOT NULL, brief TEXT NOT NULL DEFAULT '', status TEXT NOT NULL DEFAULT 'idea' CHECK(status IN ('idea','draft','media_generation','ready_for_review','approved','scheduled','published','failed','archived')), scheduled_for INTEGER, created_at INTEGER NOT NULL DEFAULT (unixepoch()*1000), updated_at INTEGER NOT NULL DEFAULT (unixepoch()*1000));
CREATE INDEX content_items_business_status_idx ON content_items(business_id,status); CREATE INDEX content_items_schedule_idx ON content_items(scheduled_for);
CREATE TABLE content_variants (id TEXT PRIMARY KEY NOT NULL, content_item_id TEXT NOT NULL REFERENCES content_items(id) ON DELETE CASCADE, platform TEXT NOT NULL, copy TEXT NOT NULL DEFAULT '', metadata_json TEXT NOT NULL DEFAULT '{}', created_at INTEGER NOT NULL DEFAULT (unixepoch()*1000), updated_at INTEGER NOT NULL DEFAULT (unixepoch()*1000));
CREATE UNIQUE INDEX content_variants_item_platform_uidx ON content_variants(content_item_id,platform);
CREATE TABLE generation_jobs (id TEXT PRIMARY KEY NOT NULL, content_item_id TEXT REFERENCES content_items(id) ON DELETE SET NULL, provider TEXT NOT NULL, model TEXT NOT NULL, prompt TEXT NOT NULL, source_asset_ids_json TEXT NOT NULL DEFAULT '[]', settings_json TEXT NOT NULL DEFAULT '{}', status TEXT NOT NULL DEFAULT 'queued', error_message TEXT, started_at INTEGER, completed_at INTEGER, created_at INTEGER NOT NULL DEFAULT (unixepoch()*1000), updated_at INTEGER NOT NULL DEFAULT (unixepoch()*1000));
CREATE INDEX generation_jobs_content_idx ON generation_jobs(content_item_id);
CREATE TABLE generation_outputs (id TEXT PRIMARY KEY NOT NULL, generation_job_id TEXT NOT NULL REFERENCES generation_jobs(id) ON DELETE CASCADE, media_asset_id TEXT NOT NULL REFERENCES media_assets(id) ON DELETE RESTRICT, provider_output_id TEXT, metadata_json TEXT NOT NULL DEFAULT '{}', created_at INTEGER NOT NULL DEFAULT (unixepoch()*1000), updated_at INTEGER NOT NULL DEFAULT (unixepoch()*1000));
CREATE INDEX generation_outputs_job_idx ON generation_outputs(generation_job_id);
CREATE TABLE social_accounts (id TEXT PRIMARY KEY NOT NULL, business_id TEXT NOT NULL REFERENCES businesses(id) ON DELETE CASCADE, platform TEXT NOT NULL, external_account_id TEXT NOT NULL, display_name TEXT NOT NULL, credential_key TEXT, enabled INTEGER NOT NULL DEFAULT 1, created_at INTEGER NOT NULL DEFAULT (unixepoch()*1000), updated_at INTEGER NOT NULL DEFAULT (unixepoch()*1000));
CREATE UNIQUE INDEX social_accounts_external_uidx ON social_accounts(platform,external_account_id);
CREATE TABLE scheduled_posts (id TEXT PRIMARY KEY NOT NULL, content_variant_id TEXT NOT NULL REFERENCES content_variants(id) ON DELETE CASCADE, social_account_id TEXT NOT NULL REFERENCES social_accounts(id) ON DELETE RESTRICT, scheduled_for INTEGER NOT NULL, status TEXT NOT NULL DEFAULT 'scheduled', idempotency_key TEXT NOT NULL, created_at INTEGER NOT NULL DEFAULT (unixepoch()*1000), updated_at INTEGER NOT NULL DEFAULT (unixepoch()*1000));
CREATE UNIQUE INDEX scheduled_posts_idempotency_uidx ON scheduled_posts(idempotency_key); CREATE INDEX scheduled_posts_due_idx ON scheduled_posts(status,scheduled_for);
CREATE TABLE publish_attempts (id TEXT PRIMARY KEY NOT NULL, scheduled_post_id TEXT NOT NULL REFERENCES scheduled_posts(id) ON DELETE CASCADE, idempotency_key TEXT NOT NULL, attempt_number INTEGER NOT NULL CHECK(attempt_number > 0), status TEXT NOT NULL, request_json TEXT NOT NULL DEFAULT '{}', response_json TEXT, error_message TEXT, attempted_at INTEGER NOT NULL, created_at INTEGER NOT NULL DEFAULT (unixepoch()*1000), updated_at INTEGER NOT NULL DEFAULT (unixepoch()*1000));
CREATE UNIQUE INDEX publish_attempts_number_uidx ON publish_attempts(scheduled_post_id,attempt_number); CREATE INDEX publish_attempts_key_idx ON publish_attempts(idempotency_key);
CREATE TABLE published_posts (id TEXT PRIMARY KEY NOT NULL, scheduled_post_id TEXT NOT NULL REFERENCES scheduled_posts(id) ON DELETE CASCADE, external_post_id TEXT NOT NULL, external_url TEXT, published_at INTEGER NOT NULL, created_at INTEGER NOT NULL DEFAULT (unixepoch()*1000), updated_at INTEGER NOT NULL DEFAULT (unixepoch()*1000));
CREATE UNIQUE INDEX published_posts_schedule_uidx ON published_posts(scheduled_post_id);
CREATE TABLE analytics_snapshots (id TEXT PRIMARY KEY NOT NULL, published_post_id TEXT NOT NULL REFERENCES published_posts(id) ON DELETE CASCADE, impressions INTEGER, reach INTEGER, engagements INTEGER, clicks INTEGER, raw_json TEXT NOT NULL DEFAULT '{}', captured_at INTEGER NOT NULL, created_at INTEGER NOT NULL DEFAULT (unixepoch()*1000), updated_at INTEGER NOT NULL DEFAULT (unixepoch()*1000));
CREATE INDEX analytics_snapshots_post_time_idx ON analytics_snapshots(published_post_id,captured_at);
CREATE TABLE approval_events (id TEXT PRIMARY KEY NOT NULL, content_item_id TEXT NOT NULL REFERENCES content_items(id) ON DELETE CASCADE, action TEXT NOT NULL, actor TEXT NOT NULL, notes TEXT, occurred_at INTEGER NOT NULL, created_at INTEGER NOT NULL DEFAULT (unixepoch()*1000), updated_at INTEGER NOT NULL DEFAULT (unixepoch()*1000));
CREATE INDEX approval_events_content_idx ON approval_events(content_item_id,occurred_at);
CREATE TABLE app_settings (key TEXT PRIMARY KEY NOT NULL, value_json TEXT NOT NULL, created_at INTEGER NOT NULL DEFAULT (unixepoch()*1000), updated_at INTEGER NOT NULL DEFAULT (unixepoch()*1000));
CREATE TABLE backup_records (id TEXT PRIMARY KEY NOT NULL, path TEXT NOT NULL, status TEXT NOT NULL, byte_size INTEGER, checksum_sha256 TEXT, app_version TEXT NOT NULL, schema_version INTEGER NOT NULL, error_message TEXT, completed_at INTEGER, created_at INTEGER NOT NULL DEFAULT (unixepoch()*1000), updated_at INTEGER NOT NULL DEFAULT (unixepoch()*1000));
CREATE TABLE audit_logs (id TEXT PRIMARY KEY NOT NULL, action TEXT NOT NULL, entity_type TEXT, entity_id TEXT, actor TEXT NOT NULL DEFAULT 'local-user', outcome TEXT NOT NULL, details_json TEXT NOT NULL DEFAULT '{}', occurred_at INTEGER NOT NULL, created_at INTEGER NOT NULL DEFAULT (unixepoch()*1000), updated_at INTEGER NOT NULL DEFAULT (unixepoch()*1000));
CREATE INDEX audit_logs_action_time_idx ON audit_logs(action,occurred_at);

PRAGMA user_version = 1;
